  const getNextAccount = () => {
    const accountMeta = (instruction.accounts as TAccountMetas)[accountIndex]!;
    accountIndex += 1;
    return accountMeta;
  };
  return {
    programAddress: instruction.programAddress,
    accounts: {
      jackpotState: getNextAccount(),
      round: getNextAccount(),
      randomnessRequest: getNextAccount(),
      platformConfig: getNextAccount(),
      treasury: getNextAccount(),
    },
    data: getSettleJackpotInstructionDataDecoder().decode(instruction.data),
  };
